const updateUserProfile = `-- name: UpdateUserProfile :one
UPDATE users SET display_name = $2, bio = $3, locale = $4, updated_at = now()
WHERE id = $1 RETURNING id, email, password_hash, role, display_name, bio, status, locale, totp_enc, totp_confirmed, totp_pending_enc, last_login_at, created_at, updated_at
`

type UpdateUserProfileParams struct {
	ID          uuid.UUID
	DisplayName string
	Bio         string
	Locale      string
}

func (q *Queries) UpdateUserProfile(ctx context.Context, arg UpdateUserProfileParams) (User, error) {
	row := q.db.QueryRow(ctx, updateUserProfile,
		arg.ID,
		arg.DisplayName,
		arg.Bio,
		arg.Locale,
	)
	var i User
	err := row.Scan(
		&i.ID,
		&i.Email,
		&i.PasswordHash,
		&i.Role,
		&i.DisplayName,
		&i.Bio,
		&i.Status,
		&i.Locale,
		&i.TotpEnc,
		&i.TotpConfirmed,
		&i.TotpPendingEnc,
		&i.LastLoginAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

